class DNode:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def push_back(self, data):
        node = DNode(data)
        if not self.head:
            self.head = self.tail = node
            return
        node.prev = self.tail
        self.tail.next = node
        self.tail = node

    def push_front(self, data):
        node = DNode(data)
        if not self.head:
            self.head = self.tail = node
            return
        node.next = self.head
        self.head.prev = node
        self.head = node

    def delete_node(self, node):
        if node.prev:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev

    def display_forward(self):
        elements, curr = [], self.head
        while curr:
            elements.append(str(curr.data))
            curr = curr.next
        return "NULL ⇄ " + " ⇄ ".join(elements) + " ⇄ NULL"

    def display_backward(self):
        elements, curr = [], self.tail
        while curr:
            elements.append(str(curr.data))
            curr = curr.prev
        return "NULL ⇄ " + " ⇄ ".join(elements) + " ⇄ NULL"

