    [0,   5,  INF, 10],
    [INF, 0,   3, INF],
    [INF, INF, 0,   1],
    [INF, INF, INF,  0]
]
result = floyd_warshall(graph)
for row in result:
    print([x if x != INF else "INF" for x in row])

def dijkstra(adj, src, V):
    dist = [INF] * V
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

